"""Inspect report.pdf: xref kind, object count, catalog, page count, encryption."""
import os
import re
import sys
import zlib

DATA_PATH = "report.pdf"

WS = b" \t\r\n\x00\x0c"
DELIMS = b"()<>[]{}/%"


def skip_ws(data, pos):
    while pos < len(data):
        c = data[pos:pos + 1]
        if c in WS:
            pos += 1
        elif c == b"%":
            nl = data.find(b"\n", pos)
            cr = data.find(b"\r", pos)
            ends = [e for e in (nl, cr) if e != -1]
            if not ends:
                return len(data)
            pos = min(ends) + 1
        else:
            break
    return pos


def parse_value(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise ValueError("EOF in value")
    c = data[pos:pos + 1]
    if c == b"<":
        if data.startswith(b"<<", pos):
            return parse_dict(data, pos)
        end = data.find(b">", pos + 1)
        if end == -1:
            raise ValueError("unterminated hex string")
        hx = data[pos + 1:end]
        if len(hx) % 2:
            hx += b"0"
        return (b"str", bytes.fromhex(hx.decode("ascii"))), end + 1
    if c == b"(":
        i = pos + 1
        depth = 1
        out = bytearray()
        while i < len(data):
            ch = data[i]
            if ch == 0x5C:
                if i + 1 >= len(data):
                    break
                nxt = data[i + 1]
                mapping = {ord("n"): 10, ord("r"): 13, ord("t"): 9, ord("b"): 8, ord("f"): 12}
                if nxt in mapping:
                    out.append(mapping[nxt]); i += 2
                elif nxt in b"\\()":
                    out.append(nxt); i += 2
                elif 48 <= nxt <= 55:
                    j = i + 1
                    octdig = bytearray()
                    while j < len(data) and j < i + 4 and 48 <= data[j] <= 55:
                        octdig.append(data[j]); j += 1
                    out.append(int(bytes(octdig), 8) & 0xFF); i = j
                else:
                    out.append(nxt); i += 2
                continue
            if ch == 0x28:
                depth += 1
            elif ch == 0x29:
                depth -= 1
                if depth == 0:
                    return (b"str", bytes(out)), i + 1
            out.append(ch)
            i += 1
        raise ValueError("unterminated literal string")
    if c == b"[":
        pos2 = pos + 1
        arr = []
        while True:
            pos2 = skip_ws(data, pos2)
            if pos2 >= len(data):
                raise ValueError("unterminated array")
            if data[pos2:pos2 + 1] == b"]":
                return arr, pos2 + 1
            v, pos2 = parse_value(data, pos2)
            arr.append(v)
    if c == b"/":
        i = pos + 1
        name = bytearray()
        while i < len(data) and data[i:i + 1] not in DELIMS and data[i:i + 1] not in WS:
            name.append(data[i]); i += 1
        return (b"name", bytes(name)), i
    m = re.match(rb"[+-]?(\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        tok = m.group(0)
        after = pos + m.end()
        after = skip_ws(data, after)
        m2 = re.match(rb"\d+", data[after:after + 64])
        if m2:
            after2 = after + m2.end()
            after2 = skip_ws(data, after2)
            if data[after2:after2 + 1] == b"R":
                return ("ref", int(tok), int(m2.group(0))), after2 + 1
        if b"." in tok:
            return float(tok), pos + m.end()
        return int(tok), pos + m.end()
    m = re.match(rb"[A-Za-z]+", data[pos:pos + 32])
    if m:
        kw = m.group(0)
        if kw == b"true":
            return True, pos + 4
        if kw == b"false":
            return False, pos + 5
        if kw == b"null":
            return None, pos + 4
    raise ValueError("cannot parse at %d: %r" % (pos, data[pos:pos + 24]))


def parse_dict(data, pos):
    assert data.startswith(b"<<", pos)
    d = {}
    pos += 2
    while True:
        pos = skip_ws(data, pos)
        if pos >= len(data):
            raise ValueError("EOF in dict")
        if data.startswith(b">>", pos):
            return d, pos + 2
        v, pos = parse_value(data, pos)
        if not (isinstance(v, tuple) and v and v[0] == b"name"):
            raise ValueError("dict key is not a name")
        v2, pos = parse_value(data, pos)
        d[v[1]] = v2


def read_object_at(data, offset):
    m = re.search(rb"(\d+)\s+(\d+)\s+obj", data[offset:offset + 64])
    if not m:
        raise ValueError("no object header at %d" % offset)
    num, gen = int(m.group(1)), int(m.group(2))
    pos = offset + m.start() + m.end()
    pos = skip_ws(data, pos)
    d, stream = None, None
    if data.startswith(b"<<", pos):
        d, pos = parse_dict(data, pos)
        pos = skip_ws(data, pos)
        if data.startswith(b"stream", pos):
            s = pos + 6
            if data.startswith(b"\r\n", s):
                s += 2
            elif s < len(data) and data[s:s + 1] in (b"\r", b"\n"):
                s += 1
            length = d.get(b"Length")
            if isinstance(length, int):
                end = s + length
                if data[end:end + 9] == b"endstream":
                    pos = end + 9
                else:
                    e = data.find(b"endstream", s)
                    if e == -1:
                        raise ValueError("no endstream")
                    pos = e + 9
            else:
                e = data.find(b"endstream", s)
                if e == -1:
                    raise ValueError("no endstream")
                pos = e + 9
            stream = data[s:pos - 9]
    e = data.find(b"endobj", pos)
    if e == -1:
        raise ValueError("no endobj for object %d" % num)
    raw = data[offset:e + 6]
    return num, gen, d, stream, raw


def parse_classic(data, off):
    pos = off + 4
    objmap = {}
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b"trailer", pos):
            tdict, _ = parse_dict(data, pos + 7)
            prev = tdict.get(b"Prev")
            if isinstance(prev, tuple) and prev[0] == "ref":
                prev = prev[1]
            return objmap, tdict, prev
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:pos + 64])
        if not m:
            raise ValueError("bad xref subsection at %d" % pos)
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        for i in range(count):
            line = data[pos:pos + 20]
            if len(line) < 20:
                raise ValueError("truncated xref entry")
            offs = int(line[0:10])
            gen = int(line[11:16])
            typ = line[17:18]
            objmap[start + i] = (1, offs, gen) if typ == b"n" else (0, 0, 0)
            pos += 20


def decompress_stream(d, raw):
    flt = d.get(b"Filter")
    if flt is None:
        return raw
    if isinstance(flt, tuple) and flt[0] == b"name":
        filters = [flt[1]]
    elif isinstance(flt, list):
        filters = [f[1] if isinstance(f, tuple) and f[0] == b"name" else f for f in flt]
    else:
        filters = []
    for f in filters:
        if f in (b"FlateDecode", b"Fl"):
            raw = zlib.decompress(raw)
        elif f == b"ASCIIHexDecode":
            raw = bytes.fromhex(raw.strip().rstrip(b">").decode("ascii"))
        else:
            raise ValueError("unsupported filter %r" % f)
    return raw


def parse_xref_stream(data, off):
    num, gen, d, stream, _ = read_object_at(data, off)
    if not d or d.get(b"Type") != (b"name", b"XRef"):
        raise ValueError("object at %d is not an XRef stream" % off)
    W = d.get(b"W")
    if not isinstance(W, list) or len(W) != 3:
        raise ValueError("bad /W in xref stream")
    w1, w2, w3 = (int(x) for x in W)
    row = w1 + w2 + w3
    Index = d.get(b"Index", [0, int(d.get(b"Size", 0))])
    content = decompress_stream(d, stream)
    objmap = {}
    k = 0
    for i in range(0, len(Index), 2):
        start, count = int(Index[i]), int(Index[i + 1])
        for j in range(count):
            if k + row > len(content):
                raise ValueError("xref stream data too short")
            seg = content[k:k + row]
            k += row
            t = int.from_bytes(seg[0:w1], "big") if w1 else 0
            f2 = int.from_bytes(seg[w1:w1 + w2], "big") if w2 else 0
            f3 = int.from_bytes(seg[w1 + w2:], "big") if w3 else 0
            objnum = start + j
            if t == 1:
                objmap[objnum] = (1, f2, f3)
            elif t == 2:
                objmap[objnum] = (2, f2, f3)
            else:
                objmap[objnum] = (0, 0, 0)
    prev = d.get(b"Prev")
    if isinstance(prev, tuple) and prev[0] == "ref":
        prev = prev[1]
    return objmap, d, prev


def collect_xrefs(data):
    idx = data.rfind(b"startxref")
    if idx == -1:
        raise ValueError("no startxref found")
    sx = int(re.search(rb"startxref\s+(\d+)", data[idx:idx + 32]).group(1))
    sections = []
    seen = set()
    off = sx
    used_xref_stream = False
    while off is not None:
        if off in seen:
            break
        seen.add(off)
        if data[off:off + 4] == b"xref":
            om, td, prev = parse_classic(data, off)
        else:
            om, td, prev = parse_xref_stream(data, off)
            used_xref_stream = True
        sections.append((om, td))
        off = prev
        if len(seen) > 100:
            raise ValueError("xref chain too long (possible loop)")
    objmap = {}
    trailer = sections[0][1] if sections else {}
    for om, _td in reversed(sections):  # oldest -> newest; newest overrides
        objmap.update(om)
    return objmap, trailer, used_xref_stream


def count_pages(data, objmap, trailer):
    root = trailer.get(b"Root")
    if not isinstance(root, tuple) or root[0] != "ref":
        raise ValueError("no /Root in trailer")
    _, _, d, _, _ = read_object_at(data, objmap[root[1]][1])
    pnum = d[b"Pages"][1]

    def walk(n):
        _, _, pd, _, _ = read_object_at(data, objmap[n][1])
        kids = pd.get(b"Kids")
        if kids is None:
            return 1
        total = 0
        for kid in kids:
            total += walk(kid[1])
        return total

    return walk(pnum), root[1], pnum


def main():
    if not os.path.exists(DATA_PATH):
        print("ERROR: report.pdf not found")
        sys.exit(1)
    data = open(DATA_PATH, "rb").read()
    print("report.pdf size: %d bytes" % len(data))
    objmap, trailer, used_stream = collect_xrefs(data)
    print("xref kind: %s" % ("xref stream" if used_stream else "classic table"))
    print("objects in map: %d, max object number: %d" % (len(objmap), max(objmap)))
    if b"Encrypt" in trailer:
        print("ERROR: report.pdf is encrypted; cannot process")
        sys.exit(1)
    try:
        pages, rootnum, rootpages = count_pages(data, objmap, trailer)
        print("catalog object: %d, root pages object: %d, page count: %d" % (rootnum, rootpages, pages))
    except Exception as e:
        print("ERROR parsing pages tree: %s" % e)
        sys.exit(1)


if __name__ == "__main__":
    main()

